def generate_inputs(device):
    # Create structured high-variance input
    # Alternating extreme positive/negative values
    x = torch.zeros(128, 512, dtype=torch.float32, device=device)
    # Create a pattern that produces varying GEMM outputs
    for i in range(512):
        if i % 4 == 0:
            x[:, i] = 5.0  # Large positive
        elif i % 4 == 1:
            x[:, i] = -5.0  # Large negative  
        elif i % 4 == 2:
            x[:, i] = 0.5  # Small positive
        else:
            x[:, i] = -0.5  # Small negative
    return [x]
